    "home.tech_title": "WebAvatar Engine",
    "home.tech_subtitle": "Unified Agent Execution & Site Interoperability",
    "home.tech_desc": "Unlike standard text-based bots, WebAvatar scans the DOM and interacts directly with elements. It achieves smooth navigation and low token overhead by adhering to the following rules:",
    "home.rule1_title": "01 / Event-Driven Routing",
    "home.rule1_desc": "When the agent decides to transition to a new page, it dispatches a cancelable 'webavatar-navigate' CustomEvent. Our single-page routing intercepts this event and updates React Router, preventing hard page reloads and keeping the speech session intact.",
    "home.rule2_title": "02 / Declarative Focus Hooks",
    "home.rule2_desc": "We anchor elements using unique IDs (e.g. #nav-flight, #nav-contact). The WebAvatar engine reads these anchors and triggers smooth scrolling, visual focal ring animations, and speech-associated highlights dynamically.",
