    "about.badge": "Our Identity",
    "about.title": "Pioneering Conversational Intelligence",
    "about.subtitle": "Botnoi Group was founded with a singular mission: to make advanced artificial intelligence accessible, hyper-localized, and highly transactional for businesses in Southeast Asia.",
    "about.purpose_title": "Our Purpose",
    "about.purpose_desc1": "We believe that human-machine interaction should be frictionless, natural, and highly intuitive. By bridging conversational NLP, synthetic human acoustics, and interactive 3D digital avatars, we create the digital workforces of tomorrow.",
