    "about.timeline_2022_desc": "Unveiled our state-of-the-art Text-to-Speech (TTS) engine, introducing over 100 near-human synthetic voices across 10 Southeast Asian languages. Adopted by leading hospital channels and public sectors.",
    "about.timeline_2026_title": "WebAvatar & Virtual Humans",
    "about.timeline_2026_desc": "Pioneering the integration of 3D virtual agents directly embedded into website layers. Launched WebAvatar, enabling virtual agents to talk verbally, answer complex user questions, and perform autonomous website scrolling and routing.",
    "about.competency_title": "Our Core Competencies",
    "about.competency_subtitle": "Proprietary systems designed and maintained in-house by Botnoi's research division.",
    "about.comp1_title": "01 / Custom Southeast Asian Tokenizers",
    "about.comp1_desc": "Unlike Western NLP frameworks that struggle with continuous-script languages (such as Thai, Lao, and Burmese) that lack clear word boundaries, Botnoi's proprietary tokenization models parse continuous sentences with up to 98% accuracy.",
    "about.comp2_title": "02 / Acoustic Cloned Synthetic Voices",
    "about.comp2_desc": "Our speech labs clone human voices from less than 30 minutes of high-quality sample audio. We generate natural acoustics with customizable emotional states, pacing variations, and localized accents suitable for regional audiences.",
    "about.comp3_title": "03 / Multi-Agent Collaboration",
    "about.comp3_desc": "We build specialized collaborative agent pipelines. Under a single avatar interface, different sub-agents coordinate with one another to resolve complex transactions, pass contextual memory data, and execute back-office database actions.",
    "about.comp4_title": "04 / Interactive DOM Mapping",
