    "contact.faq_subheading": "Read quick answers about our services. Your WebAvatar can scroll here to review details!",
    "contact.faq_q1": "What is WebAvatar and how does it integrate into my site?",
    "contact.faq_a1": "WebAvatar is a visual digital human assistant loaded via a lightweight JavaScript SDK (our custom script tag). It runs inside standard browser web layers and can navigate pages, scroll to designated HTML elements (like #pricing), trigger native single-page-app (SPA) routes, and verbally guide your visitors using synthetic speech.",
    "contact.faq_q2": "Does the speech model support continuous Thai acoustics?",
    "contact.faq_a2": "Yes. Our generative voice models are trained on regional audio archives, offering rich acoustic mapping for continuous Thai dialects, complete with natural pacing, word bridging, and tone inflection appropriate for local audiences.",
