    "showcase.desc_accommodation": "Resort & Hotel Booking: Complete reservation system featuring room catalogs, date selectors, pricing calculations, and confirmation views.",
    "showcase.desc_flight": "Flight Booking Engine: Domestic airline booking portal with interactive passenger inputs, seat mapping, and simulated boarding pass generation.",
    "showcase.desc_restaurant": "Restaurant Ordering App: Digital dining menu order application with item categorization, shopping cart, checkout billing, and live invoices.",
    "showcase.desc_ecommerce": "Tech E-Shop Storefront: Complete consumer electronics retail site with category filtering, shopping cart updates, and invoice receipts.",
    "showcase.desc_tn01": "Online Learning Hub: Comprehensive e-learning platform featuring course catalogs, video lessons, progress tracking, interactive quizzes, and student certification.",
    "showcase.desc_tn03": "Skincare & Beauty Store: Premium dermatological shop offering skin analysis, product routines, ingredient guides, shopping cart, and online order confirmation.",
    "showcase.desc_tn04": "Interactive Travel & Map Portal: Geographic exploration platform with interactive route mapping, location search, itinerary planning, and landmark guides.",
    "showcase.desc_tn05": "Hospital & Medical Services Portal: Modern healthcare portal with online doctor appointment booking, department directory, medical packages, and health test results.",
    "showcase.desc_tn06": "Botnoi AI Developer API Platform: Comprehensive Thai AI services portal featuring Speech-to-Text, Text-to-Speech, Chat AI, Voice Clone, API SDKs, and subscription plans.",
    "showcase.desc_tn07": "Digital Restaurant & Ordering App: Interactive dining experience featuring online digital menus, table reservation, customized food ordering, and instant billing.",
    "showcase.desc_tn09": "Real-Time AI Voice Translation & TTS Portal: Advanced Speech-to-Speech translation platform featuring instant multilingual text-to-speech, voice conversion, real-time audio playback, and multi-language support.",
    "showcase.desc_tn10": "AC Service & Repair Booking: Professional air conditioning maintenance portal for technician scheduling, cleaning packages, emergency repair, and service tracking.",
    "showcase.desc_tn11": "Pharmacy & Medication Consultation Portal: Online healthcare platform featuring licensed pharmacist consultation, prescription medicine ordering, symptom guidance, and home drug delivery.",
    "showcase.desc_tn14": "Artisanal Coffee & Cafe Portal: Specialty coffee shop site offering custom bean ordering, drink customization, loyalty points, and pickup scheduling.",
    "showcase.desc_tn16": "Fitness & Personal Coaching Hub: Comprehensive wellness platform with workout plans, personal trainer bookings, progress tracking, and nutrition guides.",
