    "home.tech_desc": "แตกต่างจากแชทบอทข้อความทั่วไป WebAvatar วิเคราะห์โครงสร้าง DOM และโต้ตอบกับปุ่มต่าง ๆ บนจอโดยตรง เพื่อการนำทางที่ราบรื่นและใช้ข้อมูลโทเคนอย่างคุ้มค่า ผ่านหลักการดังนี้:",
    "home.rule1_title": "01 / การนำทางด้วย Event",
    "home.rule1_desc": "เมื่ออวตาร์ต้องการเปลี่ยนหน้าเว็บ มันจะส่ง CustomEvent ชื่อ 'webavatar-navigate' ออกมา ระบบนำทางแบบ SPA ของเราจะดักจับเหตุการณ์นี้เพื่ออัปเดต React Router ป้องกันการรีโหลดหน้าใหม่และรักษาการพูดคุยไว้",
    "home.rule2_title": "02 / โฟกัสเป้าหมายเชิงประกาศ",
    "home.rule2_desc": "เรายึดโยงปุ่มสำคัญด้วย ID (เช่น #nav-flight, #nav-contact) กลไกของ WebAvatar จะอ่านตำแหน่งปุ่มและทำการเลื่อนหน้าจอ โชว์เอฟเฟกต์วงแหวนสีรอบปุ่ม และเน้นเสียงพูดตามช่วงที่สอดคล้องกัน",
    "home.rule3_title": "03 / การกรอกข้อมูลและตรวจสอบแบบไดนามิก",
    "home.rule3_desc": "ฟอร์มฝั่งลูกค้าทั้งหมดถูกผูกไว้กับการตรวจสอบมาตรฐาน HTML5 เมื่อ WebAvatar ต้องการกรอกข้อมูล มันจะยิงคำสั่งเปลี่ยนค่า inputs ดั้งเดิมของเบราว์เซอร์ เพื่อให้สเตทของ React อัปเดตอย่างสมบูรณ์",
