    "showcase.no_projects_desc": "กรุณาลองปรับปรุงคำค้นหาหรือตัวกรองใหม่อีกครั้ง",
    "showcase.desc_accommodation": "ระบบจองที่พักและรีสอร์ท: บริการค้นหาห้องพัก เช็คห้องว่าง ระบุวันเข้าพัก คำนวณราคาห้องพัก และยืนยันการจอง",
    "showcase.desc_flight": "ระบบจองตั๋วเครื่องบิน: ค้นหาเที่ยวบิน ระบุจำนวนผู้โดยสาร เลือกที่นั่งบนเครื่องบิน และการออกบอร์ดดิ้งพาสจำลอง",
    "showcase.desc_restaurant": "ระบบสั่งอาหารและรูมเซอร์วิส: เมนูอาหารออนไลน์พร้อมระบบจัดการตะกร้าสินค้า สรุปรายการสั่งซื้อ และพิมพ์ใบเสร็จแบบเรียลไทม์",
    "showcase.desc_ecommerce": "ร้านค้าออนไลน์อุปกรณ์ไอที: แหล่งรวมแก็ดเจ็ตไอที คัดกรองหมวดหมู่สินค้า หยิบใส่ตะกร้า ชำระเงิน และออกใบเสร็จรับเงิน",
    "showcase.desc_tn01": "ระบบเรียนออนไลน์ครบวงจร: แพลตฟอร์มคอร์สเรียนออนไลน์ ค้นหาบทเรียน ติดตามความก้าวหน้า ทำแบบทดสอบ และรับวุฒิบัตรจำลอง",
    "showcase.desc_tn03": "ร้านค้าสกินแคร์และดูแลผิวพรรณ: แหล่งรวมผลิตภัณฑ์เวชสำอาง ค้นหารูทีนดูแลผิว คัดกรองส่วนผสม ระบบตะกร้าสินค้า และชำระเงินออนไลน์",
    "showcase.desc_tn04": "ระบบแผนที่และการนำทางอินเทอร์แอคทีฟ: ค้นหาสถานที่ วางแผนการเดินทาง คำนวณเส้นทาง และแนะนำจุดเช็คอินสถานที่ท่องเที่ยว",
    "showcase.desc_tn05": "พอร์ทัลโรงพยาบาลและบริการทางการแพทย์: นัดหมายแพทย์ออนไลน์ ค้นหาแผนกรักษา แพ็กเกจตรวจสุขภาพ และบริการข้อมูลด้านสุขภาพ",
    "showcase.desc_tn06": "พอร์ทัล Botnoi AI API สำหรับนักพัฒนา: แพลตฟอร์มบริการ AI ภาษาไทยครบวงจร ทั้งแปลงเสียงเป็นข้อความ สังเคราะห์เสียงพูด โคลนเสียง สนทนา AI และแพ็กเกจ API",
    "showcase.desc_tn07": "ระบบสั่งอาหารและจองโต๊ะร้านอาหาร: เมนูอาหารดิจิทัล จองโต๊ะออนไลน์ สั่งอาหารปรับแต่งรสชาติ และระบบสรุปรายการใบเสร็จเรียลไทม์",
    "showcase.desc_tn09": "ระบบแปลภาษาและสังเคราะห์เสียง AI เรียลไทม์: แพลตฟอร์มแปลภาษาจากเสียงเป็นเสียง (Speech-to-Speech) แปลข้อความ สังเคราะห์เสียงพูด (TTS) สมจริง รองรับหลายภาษาแบบเรียลไทม์",
    "showcase.desc_tn10": "บริการล้างและซ่อมเครื่องปรับอากาศ: ระบบนัดหมายช่างบริการล้างแอร์ ซ่อมบำรุง ตรวจเช็คราคาแพ็กเกจ และติดตามสถานะบริการ",
    "showcase.desc_tn11": "ระบบปรึกษาและสั่งซื้อยาออนไลน์โดยเภสัชกร: แพลตฟอร์มบริการสุขภาพ ค้นหาและปรึกษาเรื่องยากับเภสัชกรผู้เชี่ยวชาญ สั่งซื้อยาตามคำแนะนำ ประเมินอาการเบื้องต้น และจัดส่งยาถึงบ้าน",
    "showcase.desc_tn14": "คาเฟ่และร้านกาแฟสเปเชียลตี้: เมนูกาแฟสดและเบเกอรี่ เลือกเมล็ดกาแฟและระดับความหวาน สั่งซื้อล่วงหน้า และระบบสะสมแต้ม",
    "showcase.desc_tn16": "ศูนย์ฟิตเนสและโค้ชชิ่งออกกำลังกาย: แพลตฟอร์มรวมตารางออกกำลังกาย นัดหมายเทรนเนอร์ส่วนตัว ติดตามผลลัพธ์สุขภาพ และแนะนำโภชนาการ",
    "showcase.type_tn01": "เรียนออนไลน์",
    "showcase.type_tn03": "บิวตี้",
