    "showcase.desc_tn19": "ร้านค้าเฟอร์นิเจอร์และของตกแต่งบ้าน: ระบบสั่งซื้อเฟอร์นิเจอร์ออนไลน์แบบครบวงจร โชว์รูมเสมือนจริง แคตตาล็อกสินค้า ดีไซน์ตกแต่งห้อง และระบบชำระเงิน",
