    "site2026.about_title": "关于网站 2026",
    "site2026.about_desc": "国家创新机构（公共组织）或 NIA 认识到持续发展国家创新体系和创业生态系统的重要性。今年，Startup x Innovation Thai Expo 2026（简称 SITE 2026）以“全球创新影响力：投资年”为理念举办，旨在聚集全球创新网络，提升合作，促进知识共享，以加强生态系统。",
    "site2026.objective_title": "目标",
    "site2026.objective_1": "1. 加强本地和国际生态系统中所有部门（政府、私营部门、学术界、协会）之间的创新合作。",
    "site2026.objective_2": "2.创造商机，支持创业创新企业。",
    "site2026.objective_3": "3. 在东南亚和全球建立国际商业和创新网络，以支持经济扩张。",
