    "home.card_food_desc": "适用于 20 个房屋 (TN01-TN20) 的自适应工作空间门户，支持动态项目类型（住宿、航班预订、餐厅、电子商务）。选择 House 7 (TN07) 来测试有机客房服务餐饮演示。",
    "home.card_food_cta": "启动 TN House 门户网站",
    "home.card_alldemo_title": "所有演示 (TN01-TN20)",
    "home.card_alldemo_desc": "探索所有交互式沙箱应用程序和学生 Web 项目 (TN01–TN20)，包括航班预订、IT 商店电子商务和学生团队展示。",
    "home.card_alldemo_cta": "启动所有演示门户",
    "home.card_itstore_title": "Botnoi IT Shop — 电子商务",
    "home.card_itstore_desc": "功能齐全的科技零售店面。浏览笔记本电脑、显示器、音频和配件。演示类别过滤、购物车管理、发票结账以及带有完整 WebAvatar 语音命令导航的管理订单仪表板。",
    "home.card_itstore_cta": "启动 IT 商店演示",
    "home.card_hotel_title": "Botnoi Grand Hotel & Resort — 酒店预订",
    "home.card_hotel_desc": "交互式酒店与度假村房间预订沙盒。具有客房选择、入住日期筛选、访客数量管理和 WebAvatar 语音导航功能。",
    "home.card_hotel_cta": "启动酒店预订演示",
    "home.card_contact_title": "B2B 销售查询表",
    "home.card_contact_desc": "生产级潜在客户生成捕获表。包括验证状态、动态查询类型下拉选择、交互式常见问题解答手风琴和沙箱查询提交名册。",
    "home.card_contact_cta": "启动 B2B 询价演示",
    "home.tech_title": "WebAvatar 引擎",
    "home.tech_subtitle": "统一代理执行和站点互操作性",
    "home.tech_desc": "与标准的基于文本的机器人不同，WebAvatar 扫描 DOM 并直接与元素交互。它通过遵守以下规则来实现流畅的导航和低令牌开销：",
    "home.rule1_title": "01 / 事件驱动路由",
    "home.rule1_desc": "当代理决定转换到新页面时，它会调度可取消的“webavatar-navigate”自定义事件。我们的单页面路由拦截此事件并更新 React Router，防止硬页面重新加载并保持语音会话完整。",
    "home.rule2_title": "02 / 声明性焦点钩子",
    "home.rule2_desc": "我们使用唯一的 ID 来锚定元素（例如#nav-flight、#nav-contact）。 WebAvatar 引擎读取这些锚点并动态触发平滑滚动、视觉焦环动画和语音相关的亮点。",
    "home.rule3_title": "03 / 冗余输入验证",
    "home.rule3_desc": "所有客户端表单都连接到标准 HTML5 输入验证并触发反应性成功指示器。当 WebAvatar 代理填充字段时，它会调度本机输入事件以正确更新 React 组件状态。",
    "home.tech_cta": "将 WebAvatar 部署到您的站点",
