    "about.badge": "我们的身份",
    "about.title": "开创性的对话智能",
    "about.subtitle": "Botnoi Group 的成立有一个独特的使命：为东南亚企业提供先进的人工智能、超本地化和高度交易性的服务。",
    "about.purpose_title": "我们的目的",
    "about.purpose_desc1": "我们相信人机交互应该是无摩擦、自然且高度直观的。通过连接对话式 NLP、合成人体声学和交互式 3D 数字化身，我们打造了未来的数字化劳动力。",
    "about.purpose_desc2": "无论是自动化高频客户服务还是通过复杂的医疗保健门户引导患者，Botnoi Group 解决方案的构建都具有无与伦比的可靠性。",
    "about.vision_title": "我们的愿景",
    "about.vision_desc": "成为东南亚语音和数字人类技术的绝对标准。我们帮助区域中小型企业和企业部署最先进的虚拟代理，以提供卓越的客户满意度。",
    "about.vision_cta": "与我们的工程师联系",
    "about.journey_title": "博特诺伊之旅",
    "about.journey_subtitle": "追溯我们从曼谷一家专业人工智能初创公司到区域数字人类领导者的历史。",
    "about.timeline_2018_title": "公司成立",
    "about.timeline_2018_desc": "Botnoi Group 由一群专门的计算语言学家和神经网络工程师在泰国曼谷成立，专注于构建专业的泰语解析模型。",
    "about.timeline_2020_title": "Botnoi 人工智能发布",
    "about.timeline_2020_desc": "发布了我们的旗舰低代码人工智能聊天机器人平台（Botnoi.ai）。该平台迅速扩展，通过 LINE OA 和 Facebook Messenger 为 5,000 多家企业客户提供客户支持聊天流。",
    "about.timeline_2022_title": "Botnoi 语音推出",
    "about.timeline_2022_desc": "推出了我们最先进的文本转语音 (TTS) 引擎，引入了 10 种东南亚语言的 100 多种接近人类的合成声音。被领先的医院渠道和公共部门采用。",
    "about.timeline_2026_title": "网络头像和虚拟人",
    "about.timeline_2026_desc": "开创性地将 3D 虚拟代理直接嵌入到网站层中。推出 WebAvatar，使虚拟代理能够进行口头交谈、回答复杂的用户问题以及执行自主的网站滚动和路由。",
    "about.competency_title": "我们的核心竞争力",
    "about.competency_subtitle": "专有系统由 Botnoi 的研究部门内部设计和维护。",
    "about.comp1_title": "01 / 定制东南亚分词器",
    "about.comp1_desc": "与难以应对缺乏清晰单词边界的连续脚本语言（如泰语、老挝语和缅甸语）的西方 NLP 框架不同，Botnoi 专有的标记化模型解析连续句子的准确率高达 98%。",
    "about.comp2_title": "02 / 原声克隆合成声音",
    "about.comp2_desc": "我们的语音实验室从不到 30 分钟的高质量音频样本中克隆人声。我们生成自然的声学效果，具有可定制的情绪状态、节奏变化和适合地区观众的本地口音。",
    "about.comp3_title": "03 / 多智能体协作",
    "about.comp3_desc": "我们建立专门的协作代理管道。在单一化身界面下，不同的子代理相互协调来解决复杂的事务、传递上下文内存数据并执行后台数据库操作。",
    "about.comp4_title": "04 / 交互式 DOM 映射",
    "about.comp4_desc": "WebAvatar 代理利用实时浏览器 DOM 反射。当客户询问“你们的价格在哪里？”时，虚拟人会阅读该请求，触发页面滚动，突出显示所请求的定价行，并口头审查层级功能。",
    "about.team_title": "我们的领导团队",
    "about.team_subtitle": "与指导我们产品线、语言学研究和区域业务战略的远见卓识者会面。",
    "about.team1_role": "创始人兼首席执行官",
    "about.team1_desc": "专注于计算神经网络和区域商业战略。",
    "about.team2_role": "语音技术总监",
    "about.team2_desc": "监督文本到语音建模和情感语音克隆系统。",
    "about.team3_role": "自然语言处理主管",
    "about.team3_desc": "指导东南亚代币化和 NLP 管道开发的核心研发。",
    "about.team4_role": "WebAvatar 首席产品工程师",
    "about.team4_desc": "管理浏览器集成 SDK、渲染层和 SPA 路由插件。",
