    "showcase.desc_accommodation": "度假村及酒店预订：完整的预订系统，包含客房目录、日期选择器、价格计算和确认页面。",
    "showcase.desc_flight": "机票预订引擎：国内航空公司预订门户网站，包含交互式旅客输入、座位图和模拟登机牌生成。",
    "showcase.desc_restaurant": "餐厅点餐应用：数字化餐饮菜单点餐应用，支持商品分类、购物车、结账账单及实时发票。",
    "showcase.desc_ecommerce": "科技电子商店：完整的消费电子零售网站，支持分类筛选、购物车更新和发票收据。",
    "showcase.desc_tn01": "在线学习中心：综合在线教育平台，包含课程目录、视频教学、学习进度跟踪、互动测验和证书生成。",
    "showcase.desc_tn03": "护肤与美容商城：高端皮肤护理商店，提供肌肤测试、护肤方案、成分指南、购物车和在线结算功能。",
    "showcase.desc_tn04": "互动地图与旅游门户：地理探索平台，支持路线规划、地点搜索、行程安排和景点导览。",
    "showcase.desc_tn05": "医院与医疗服务门户：现代医疗健康平台，包含在线医生预约、科室查询、体检套餐和健康诊断。",
    "showcase.desc_tn06": "Botnoi AI 开发者 API 平台：综合泰语 AI 服务门户，包含语音转文字、语音合成、AI 聊天、声音克隆、API SDK 和订阅套餐。",
    "showcase.desc_tn07": "数字餐厅与点餐应用：互动式餐饮体验，提供电子菜单、在线订座、个性化点餐和实时结账。",
    "showcase.desc_tn09": "实时 AI 语音翻译与 TTS 平台：先进的语音到语音实时翻译系统，支持多语言文本转语音（TTS）、实时语音合成、声音转换与即时播放。",
    "showcase.desc_tn10": "空调维修与清洗预约：专业空调保养与维修服务平台，支持技师预约、清洗套餐选择和服务进度跟踪。",
    "showcase.desc_tn11": "在线药房与执业药师咨询平台：综合健康服务平台，提供执业药师在线用药咨询、药品订购、症状初步评估及安全送药到家服务。",
    "showcase.desc_tn14": "精品咖啡与饮品店：特色咖啡馆网站，支持咖啡豆选购、饮品定制、会员积分和预订自提。",
    "showcase.desc_tn16": "健身与私教指导中心：全面健康健身平台，包含训练计划、私教预约、身体数据跟踪和营养饮食建议。",
