    "home.badge": "ウェブアバターサンドボックス",
    "home.hero_title": "デジタル担当者に会う",
    "home.hero_subtitle": "Botnoi Group は、究極の WebAvatar エージェントのショーケースを紹介します。この統合サンドボックスには、自動音声、フォーム入力、ページ ルーティング用に構成された 3 つのローカライズされたビジネス アプリケーションが備えられています。",
    "home.btn_explore": "デモの使用例を調べる",
    "home.btn_tech": "ナビゲーションの仕組み",
    "home.mockup_title": "WebAvatarデジタル担当者",
    "home.mockup_desc": "私たちのビジュアル アバターは、Web ページの構造を読み取り、複雑な入力を入力し、ドロップダウン項目を選択し、内部でナビゲーションを処理します。 「フライトの予約に行く」または「グリーン カレーの食事オプションを見せて」などのコマンドを発話してみてください。",
    "home.btn_request_live": "ライブデモをリクエストする",
    "home.btn_launch_usecases": "ユースケースを開始する",
    "home.mockup_avatar_title": "Botnoi - デジタル アバター",
    "home.mockup_awaiting": "コマンドを待っています...",
    "home.stats_clients": "アクティブなクライアント",
    "home.stats_voices": "リアルな声",
    "home.stats_languages": "サポートされている言語",
    "home.select_usecase": "デモの使用例を選択してください",
    "home.usecase_subtitle": "以下から対話型ビジネス アプリケーションを選択してください。すべてのルートは WebAvatar スキャナーで検出できます。",
    "home.card_flight_title": "BotnoiAirの航空券予約",
    "home.card_flight_desc": "地域に合わせた国内航空券予約システム。往復検索フィルター、乗客数セレクター、プロモーション コード オプション、生成された搭乗券モーダル、完全な管理者予約名簿が含まれます。",
    "home.card_flight_cta": "フライト予約デモを開始",
    "home.card_food_title": "TN01-TN20 アダプティブ ワークスペース ポータル",
    "home.card_food_desc": "動的なプロジェクト タイプ (宿泊施設、航空券の予約、レストラン、電子商取引) をサポートする 20 軒の住宅 (TN01 ～ TN20) 用の適応型ワークスペース ポータル。 House 7 (TN07) を選択して、オーガニック ルームサービス ダイニングのデモをテストします。",
    "home.card_food_cta": "TNハウスポータルを立ち上げる",
    "home.card_alldemo_title": "すべてのデモ (TN01-TN20)",
    "home.card_alldemo_desc": "フライト予約、ITストア電子商取引、学生チームの成果物を含む、すべてのインタラクティブなサンドボックスアプリケーションと学生Webプロジェクト (TN01～TN20) を探索できます。",
    "home.card_alldemo_cta": "すべてのデモポータルを起動",
    "home.card_itstore_title": "Botnoi IT ショップ — 電子商取引",
    "home.card_itstore_desc": "フル装備のテクノロジー小売店。ラップトップ、モニター、オーディオ、アクセサリを閲覧します。カテゴリ フィルタリング、カート管理、請求書のチェックアウト、完全な WebAvatar 音声コマンド ナビゲーションを備えた管理注文ダッシュボードをデモンストレーションします。",
    "home.card_itstore_cta": "IT ストアのデモを開始",
    "home.card_hotel_title": "Botnoi Grand Hotel & Resort — ホテル予約",
    "home.card_hotel_desc": "インタラクティブなホテル＆リゾート客室予約サンドボックス。部屋選択、チェックイン日付フィルター、宿泊人数管理、WebAvatar音声ナビゲーション機能を搭載。",
    "home.card_hotel_cta": "ホテル予約デモを開始",
    "home.card_contact_title": "B2B営業お問い合わせフォーム",
    "home.card_contact_desc": "実稼働グレードの見込み顧客獲得フォーム。検証状態、動的な問い合わせタイプのドロップダウン選択、インタラクティブな FAQ アコーディオン、およびサンドボックス問い合わせ提出名簿が含まれます。",
    "home.card_contact_cta": "B2B 問い合わせデモを開始",
    "home.tech_title": "ウェブアバターエンジン",
    "home.tech_subtitle": "統合されたエージェントの実行とサイトの相互運用性",
    "home.tech_desc": "標準のテキストベースのボットとは異なり、WebAvatar は DOM をスキャンし、要素と直接対話します。次のルールに従うことで、スムーズなナビゲーションと低いトークン オーバーヘッドを実現します。",
    "home.rule1_title": "01 / イベント駆動型ルーティング",
    "home.rule1_desc": "エージェントが新しいページに移行することを決定すると、キャンセル可能な「webavatar-navigate」CustomEvent を送出します。シングルページルーティングはこのイベントをインターセプトして React Router を更新し、ハードページのリロードを防ぎ、音声セッションをそのまま維持します。",
    "home.rule2_title": "02 / 宣言型フォーカスフック",
    "home.rule2_desc": "一意の ID (#nav-flight、#nav-contact など) を使用して要素を固定します。 WebAvatar エンジンはこれらのアンカーを読み取り、スムーズなスクロール、視覚的なフォーカル リング アニメーション、および音声に関連したハイライトを動的にトリガーします。",
    "home.rule3_title": "03 / 冗長入力検証",
    "home.rule3_desc": "すべてのクライアント側フォームは標準の HTML5 入力検証に接続され、リアクティブな成功インジケーターをトリガーします。 WebAvatar エージェントがフィールドに値を入力すると、ネイティブ入力イベントを送出して React コンポーネントの状態を正しく更新します。",
    "home.tech_cta": "WebAvatar をサイトに導入する",
    "home.features_heading": "エンジンの機能と制約",
    "home.feat1": "継続的なタイ文字解析をサポート",
