    "itstore_item.mate80pro.desc": "HUAWEI Mate 80 Pro は 6.75 インチ LTPO OLED ディスプレイ（2832×1280、1-120Hz）、7.95mm 薄型ボディ、IP68/IP69 防水防塵、16 GB RAM + 512 GB ROM、100W 急速充電対応 5,750 mAh バッテリーを搭載しています。",
