    "itstore_item.matex7.desc": "HUAWEI Mate X7 は 8 インチ メイン OLED スクリーン、16 GB RAM + 512 GB ROM、66W 有線充電対応 5,600 mAh バッテリー、50 MP 超光感度カメラを搭載した折りたたみスマートフォンです。",
