    "itstore_item.matext.desc": "HUAWEI Mate XT ULTIMATE DESIGN は 10.2 インチまで拡張可能な 3 つ折り（Tri-fold）OLED スクリーン、Kirin 9010 チップ、16 GB RAM + 1 TB ROM、厚さ 3.6mm の極薄ボディを特徴としています。",
