    "itstore_item.mate50.desc": "HUAWEI Mate 50 は 6.7 インチ OLED スクリーン、Snapdragon 8+ Gen 1 4G チップセット、8 GB RAM + 256 GB ROM、66W SuperCharge 対応 4,460 mAh バッテリーを搭載しています。",
    "itstore_item.matexs2.name": "HUAWEI Mate Xs 2",
    "itstore_item.matexs2.specs": "7.8\" 外折り OLED · Snapdragon 888 4G · 8GB RAM · 512GB ROM",
    "itstore_item.matexs2.desc": "HUAWEI Mate Xs 2 は 7.8 インチ OLED スクリーン、Snapdragon 888 4G チップセット、8 GB RAM + 512 GB ROM、50 MP True-Chroma カメラを備えた外折りスマートフォンです。",
    "about.badge": "私たちのアイデンティティ",
    "about.title": "先駆的な会話インテリジェンス",
    "about.subtitle": "Botnoi Group は、高度な人工知能を東南アジアの企業にとってアクセスしやすく、超ローカライズされ、高度にトランザクション化できるようにするという、唯一の使命を持って設立されました。",
    "about.purpose_title": "私たちの目的",
    "about.purpose_desc1": "私たちは、人間と機械のインタラクションは摩擦がなく、自然で、非常に直観的であるべきだと信じています。会話型 NLP、合成人間音響、インタラクティブな 3D デジタル アバターを橋渡しすることで、私たちは明日のデジタル ワークフォースを創出します。",
    "about.purpose_desc2": "高頻度の顧客ケアを自動化する場合でも、複雑な医療ポータルを通じて患者を案内する場合でも、Botnoi Group のソリューションは、妥協のない信頼性で拡張できるように構築されています。",
    "about.vision_title": "私たちのビジョン",
    "about.vision_desc": "東南アジアの音声とデジタルヒューマンテクノロジーの絶対的な標準となること。当社は、地域の中小企業や企業が、優れた顧客満足度を提供する最先端の仮想エージェントを導入できるように支援します。",
    "about.vision_cta": "当社のエンジニアとつながる",
    "about.journey_title": "ボットノイの旅",
    "about.journey_subtitle": "バンコクの AI 専門スタートアップから地域のデジタル ヒューマン リーダーまでの歴史をたどります。",
    "about.timeline_2018_title": "会社設立",
    "about.timeline_2018_desc": "Botnoi Group は、特殊なタイ語解析モデルの構築に重点を置いた計算言語学者とニューラル ネットワーク エンジニアの専任集団によってタイのバンコクに設立されました。",
    "about.timeline_2020_title": "Botnoi AI の起動",
    "about.timeline_2020_desc": "当社の主力ローコード AI チャットボット プラットフォーム (Botnoi.ai) をリリースしました。このプラットフォームはすぐに拡張され、LINE OA と Facebook Messenger にわたる 5,000 を超える企業クライアントのカスタマー サポート チャット フローを強化しました。",
    "about.timeline_2022_title": "Botnoi 音声ロールアウト",
    "about.timeline_2022_desc": "最先端の Text-to-Speech (TTS) エンジンを発表し、東南アジアの 10 言語にわたる 100 以上の人間に近い合成音声を導入しました。主要な病院チャネルおよび公共部門で採用されています。",
    "about.timeline_2026_title": "ウェブアバターとバーチャルヒューマン",
    "about.timeline_2026_desc": "Web サイト層に直接埋め込まれた 3D 仮想エージェントの統合の先駆者。 WebAvatar を開始し、仮想エージェントが口頭で会話し、ユーザーの複雑な質問に答え、Web サイトの自律的なスクロールとルーティングを実行できるようにしました。",
    "about.competency_title": "私たちのコアコンピテンシー",
    "about.competency_subtitle": "Botnoi の研究部門によって社内で設計および保守されている独自のシステム。",
    "about.comp1_title": "01 / カスタム東南アジアトークナイザー",
    "about.comp1_desc": "明確な単語境界がない連続スクリプト言語 (タイ語、ラオス語、ビルマ語など) に苦戦する西洋の NLP フレームワークとは異なり、Botnoi 独自のトークン化モデルは最大 98% の精度で連続文を解析します。",
    "about.comp2_title": "02 / 音響クローン合成音声",
    "about.comp2_desc": "当社のスピーチ ラボでは、30 分未満の高品質のサンプル オーディオから人間の声のクローンを作成します。カスタマイズ可能な感情状態、ペースの変化、地域の聴衆に適した局所的なアクセントを備えた自然な音響を生成します。",
    "about.comp3_title": "03 / マルチエージェントのコラボレーション",
    "about.comp3_desc": "私たちは、特化した共同エージェント パイプラインを構築します。単一のアバター インターフェイスの下で、さまざまなサブエージェントが相互に連携して、複雑なトランザクションを解決し、コンテキスト メモリ データを渡し、バックオフィス データベース アクションを実行します。",
    "about.comp4_title": "04 / インタラクティブな DOM マッピング",
    "about.comp4_desc": "WebAvatar エージェントは、リアルタイムのブラウザ DOM リフレクションを利用します。顧客が「価格はどこですか?」と尋ねると、バーチャル ヒューマンはリクエストを読み、ページ スクロールをトリガーし、リクエストされた価格設定の行を強調表示し、階層の機能を口頭で確認します。",
    "about.team_title": "私たちのリーダーシップチーム",
    "about.team_subtitle": "当社の製品パイプライン、言語研究、地域のビジネス戦略を指揮する先見の明のある人たちを紹介します。",
    "about.team1_role": "創設者兼最高経営責任者",
    "about.team1_desc": "専門は計算ニューラルネットワークと地域ビジネス戦略。",
    "about.team2_role": "音声テクノロジー担当ディレクター",
    "about.team2_desc": "テキスト読み上げモデリングと感情的な音声クローン システムを監督します。",
    "about.team3_role": "自然言語処理責任者",
    "about.team3_desc": "東南アジアのトークン化と NLP パイプライン開発の中核となる研究開発を指揮します。",
    "about.team4_role": "WebAvatar 社リード プロダクト エンジニア",
    "about.team4_desc": "ブラウザ統合 SDK、レンダリング レイヤー、および SPA ルーティング プラグインを管理します。",
