    "contact.badge": "B2B販売に関するお問い合わせ",
    "contact.title": "デジタル体験を拡張しましょう",
    "contact.subtitle": "WebAvatar をサイトに展開すること、またはカスタム会話モデルを統合することについて質問がありますか?メッセージをお送りください。すぐにチームからご連絡いたします。",
    "contact.office_heading": "本社",
    "contact.office_subheading": "弊社の連絡先情報と営業時間は以下をご覧ください。",
    "contact.form_heading": "サンドボックスに関する問い合わせの送信",
    "contact.form_subheading": "このフォームを送信して、WebAvatar の入力とデータの送信機能をテストします。",
    "contact.form_name": "フルネーム",
