    "showcase.desc_accommodation": "リゾート＆ホテル予約：客室カタログ、日付選択、料金計算、予約確認画面を備えた完全な予約システム。",
    "showcase.desc_flight": "フライト予約エンジン：インタラクティブな乗客入力、シートマップ、模擬搭乗券生成機能を備えた国内線予約ポータル。",
    "showcase.desc_restaurant": "レストラン注文アプリ：商品カテゴリ、ショッピングカート、会計ビル、リアルタイム請求書機能を備えたデジタルメニュー注文アプリ。",
    "showcase.desc_ecommerce": "テック eショップ：カテゴリフィルタ、ショッピングカート、請求書レシートを備えた家電小売サイト。",
    "showcase.desc_tn01": "オンライン学習ハブ：コースカタログ、ビデオレッスン、学習進捗追跡、インタラクティブクイズ、修了証発行を備えた教育プラットフォーム。",
    "showcase.desc_tn03": "スキンケア＆ビューティーストア：肌診断、スキンケアルーティン、成分ガイド、ショッピングカート、オンライン決済を提供するショップ。",
    "showcase.desc_tn04": "インタラクティブマップ＆トラベルポータル：ルート検索、スポット検索、旅程作成、観光地ガイドを備えたマップ探友プラットフォーム。",
    "showcase.desc_tn05": "病院＆医療サービスポータル：オンライン医師予約、診療科検索、健康診断パッケージ、医療情報を提供するヘルスケアポータル。",
    "showcase.desc_tn06": "Botnoi AI 開発者向け API プラットフォーム：音声認識（STT）、音声合成（TTS）、AIチャット、音声クローン、API SDK、料金プランを備えたタイ語AI統合ポータル。",
    "showcase.desc_tn07": "デジタルレストラン＆注文アプリ：デジタルメニュー、オンライン席予約、カスタム注文、リアルタイム会計機能を備えたダイニングアプリ。",
    "showcase.desc_tn09": "リアルタイム AI 音声翻訳＆TTS プラットフォーム：音声から音声へのリアルタイム翻訳、自然なテキスト読み上げ（TTS）、音声変換、多言語対応を備えた統合ポータル。",
    "showcase.desc_tn10": "エアコン修理・クリーニング予約：技術者派遣予約、エアコン洗浄パッケージ、修理見積もり、サービス追跡を提供するポータル。",
    "showcase.desc_tn11": "オンライン薬局＆薬剤師相談ポータル：専門薬剤師によるオンライン服薬指導・相談、医薬品の注文、症状セルフチェック、安心の自宅配送を提供するヘルスケアプラットフォーム。",
    "showcase.desc_tn14": "スペシャルティコーヒー＆カフェ：コーヒー豆注文、ドリンクカスタマイズ、ポイントカード、事前注文受取機能を備えたカフェサイト。",
    "showcase.desc_tn16": "フィットネス＆パーソナルコーチングハブ：トレーニングプラン、専属トレーナー予約、身体データ記録、栄養アドバイスを提供するプラットフォーム。",
