    "site2026.hero_subtitle": "2026년 6월 25일~27일, 퀸 시리킷 국립 컨벤션 센터(QSNCC)",
    "site2026.about_title": "사이트 2026 소개",
    "site2026.about_desc": "국가혁신청(공공기관) 또는 NIA는 국가 혁신 시스템과 스타트업 생태계의 지속적인 발전의 중요성을 인식하고 있습니다. 올해 스타트업 x 이노베이션 태국 엑스포 2026(SITE 2026)은 글로벌 혁신 네트워크를 모으고, 협력을 강화하며, 생태계 강화를 위한 지식 공유를 촉진하기 위해 '글로벌 혁신 영향: 투자의 해'라는 컨셉으로 조직됐다.",
    "site2026.objective_title": "목표",
    "site2026.objective_1": "1. 국내 및 국제적으로 생태계 내 모든 부문(정부, 민간, 학계, 협회) 간 혁신 협력을 강화합니다.",
    "site2026.objective_2": "2. 비즈니스 기회를 창출하고 스타트업과 혁신 기반 기업을 지원합니다.",
    "site2026.objective_3": "3. 경제 확장을 지원하기 위해 동남아시아 및 전 세계에 국제 비즈니스 및 혁신 네트워크를 구축합니다.",
