    "home.card_flight_desc": "현지화된 국내 항공사 예약 시스템입니다. 왕복 여행 검색 필터, 승객 수 선택기, 프로모션 코드 옵션, 생성된 탑승권 모달 및 전체 관리자 예약 명단이 포함됩니다.",
    "home.card_flight_cta": "항공편 예약 데모 출시",
    "home.card_food_title": "TN01-TN20 적응형 작업 공간 포털",
    "home.card_food_desc": "동적 프로젝트 유형(숙박, 항공편 예약, 레스토랑, 전자 상거래)을 지원하는 20개 주택(TN01-TN20)을 위한 적응형 작업 공간 포털입니다. 유기농 룸서비스 식사 데모를 테스트하려면 House 7(TN07)을 선택하세요.",
    "home.card_food_cta": "TN하우스 포털 출시",
    "home.card_alldemo_title": "모든 데모 (TN01-TN20)",
    "home.card_alldemo_desc": "항공편 예약, IT 스토어 전자상거래 및 학생 팀 쇼케이스를 포함한 모든 대화형 샌드박스 애플리케이션과 학생 웹 프로젝트(TN01–TN20)를 둘러보세요.",
    "home.card_alldemo_cta": "모든 데모 포털 시작",
    "home.card_itstore_title": "Botnoi IT Shop — 전자상거래",
    "home.card_itstore_desc": "모든 기능을 갖춘 기술 소매점입니다. 노트북, 모니터, 오디오 및 액세서리를 찾아보세요. 완전한 WebAvatar 음성 명령 탐색 기능을 갖춘 카테고리 필터링, 장바구니 관리, 송장 결제 및 관리 주문 대시보드를 보여줍니다.",
    "home.card_itstore_cta": "IT 스토어 데모 시작",
    "home.card_hotel_title": "Botnoi Grand Hotel & Resort — 호텔 예약",
    "home.card_hotel_desc": "대화형 호텔 및 리조트 객실 예약 샌드박스. 객실 선택, 체크인 날짜 필터, 투숙객 수 관리 및 WebAvatar 음성 탐색 기능 제공.",
    "home.card_hotel_cta": "호텔 예약 데모 시작",
    "home.card_contact_title": "B2B 영업 문의 양식",
    "home.card_contact_desc": "프로덕션 등급 리드 생성 캡처 양식입니다. 유효성 검사 상태, 동적 문의 유형 드롭다운 선택, 대화형 FAQ 아코디언 및 샌드박스 문의 제출 목록이 포함되어 있습니다.",
    "home.card_contact_cta": "B2B 문의 데모 시작",
    "home.tech_title": "Web아바타 엔진",
    "home.tech_subtitle": "통합 에이전트 실행 및 사이트 상호 운용성",
    "home.tech_desc": "표준 텍스트 기반 봇과 달리 WebAvatar는 DOM을 스캔하고 요소와 직접 상호 작용합니다. 다음 규칙을 준수하여 원활한 탐색과 낮은 토큰 오버헤드를 달성합니다.",
    "home.rule1_title": "01 / 이벤트 기반 라우팅",
    "home.rule1_desc": "에이전트가 새 페이지로 전환하기로 결정하면 취소 가능한 'webavatar-navigate' CustomEvent를 전달합니다. 단일 페이지 라우팅은 이 이벤트를 가로채고 React Router를 업데이트하여 하드 페이지 다시 로드를 방지하고 음성 세션을 그대로 유지합니다.",
    "home.rule2_title": "02 / 선언적 포커스 후크",
    "home.rule2_desc": "고유 ID(예: #nav-flight, #nav-contact)를 사용하여 요소를 고정합니다. WebAvatar 엔진은 이러한 앵커를 읽고 부드러운 스크롤링, 시각적 초점 링 애니메이션 및 음성 관련 강조 표시를 동적으로 트리거합니다.",
    "home.rule3_title": "03 / 중복 입력 검증",
    "home.rule3_desc": "모든 클라이언트 측 양식은 표준 HTML5 입력 유효성 검사에 연결되어 있으며 반응적 성공 표시기를 트리거합니다. WebAvatar 에이전트가 필드를 채울 때 기본 입력 이벤트를 전달하여 React 구성 요소 상태를 올바르게 업데이트합니다.",
    "home.tech_cta": "귀하의 사이트에 WebAvatar 배포",
    "home.features_heading": "엔진 기능 및 제약",
    "home.feat1": "지속적인 태국어 스크립트 구문 분석 지원",
    "home.feat2": "동적 뷰포트 좌표 투영",
    "home.feat3": "이중 언어 음성 모델 전환",
    "home.feat4": "타사 쿠키 또는 스크립트 추적 없음",
