    "showcase.no_projects_desc": "검색 필터 또는 쿼리를 조정해 보세요.",
    "showcase.desc_accommodation": "리조트 & 호텔 예약: 객실 카탈로그, 날짜 선택기, 요금 계산 및 예약 확인 보기를 포함하는 전체 예약 시스템.",
    "showcase.desc_flight": "항공권 예약 엔진: 대화형 승객 입력, 좌석 매핑 및 모의 탑승권 생성을 갖춘 국내 항공사 예약 포털.",
    "showcase.desc_restaurant": "레스토랑 주문 앱: 품목 분류, 쇼핑 카트, 결제 청구 및 실시간 송장을 제공하는 디지털 메뉴 주문 애플리케이션.",
    "showcase.desc_ecommerce": "테크 e숍: 카테고리 필터링, 쇼핑 카트 업데이트 및 인보이스 영수증을 포함하는 소비자 전자 제품 소매 사이트.",
    "showcase.desc_tn01": "온라인 학습 허브: 강좌 카탈로그, 비디오 강의, 학습 진도 관리, 대화형 퀴즈 및 수료증 발급을 제공하는 종합 E-러닝 플랫폼.",
    "showcase.desc_tn03": "스킨케어 & 뷰티 스토어: 피부 진단, 스킨케어 루틴, 성분 가이드, 쇼핑카트 및 온라인 결제 기능을 갖춘 프리미엄 매장.",
    "showcase.desc_tn04": "대화형 지도 & 여행 포털: 경로 탐색, 장소 검색, 일정 계획 및 관광지 안내를 제공하는 지리 탐색 플랫폼.",
    "showcase.desc_tn05": "병원 & 의료 서비스 포털: 온라인 의사 진료 예약, 진료과 안내, 건강검진 패키지 및 의료 정보 종합 포털.",
    "showcase.desc_tn06": "Botnoi AI 개발자 API 플랫폼: 음성 인식(STT), 음성 합성(TTS), AI 챗봇, 보이스 클론, API SDK 및 구독 요금제를 제공하는 태국어 AI 통합 서비스 포털.",
    "showcase.desc_tn07": "디지털 레스토랑 & 주문 앱: 디지털 메뉴, 온라인 테이블 예약, 맞춤 메뉴 주문 및 실시간 영수증 결제 서비스.",
    "showcase.desc_tn09": "실시간 AI 음성 번역 및 TTS 플랫폼: 음성 대 음성 실시간 번역, 다국어 텍스트 음성 변환(TTS), 음성 합성 및 실시간 오디오 재생을 지원하는 통합 서비스.",
    "showcase.desc_tn10": "에어컨 수리 및 청소 예약: 엔지니어 방문 예약, 에어컨 세척 패키지, 수리 신청 및 서비스 진행 현황 조회 포털.",
    "showcase.desc_tn11": "온라인 약국 및 전문 약사 상담 포털: 전문 약사의 온라인 복약 지도 및 상담, 의약품 주문, 증상 사전 체크, 안전한 홈 배송 서비스를 제공하는 헬스케어 플랫폼.",
    "showcase.desc_tn14": "스페셜티 커피 & 카페 포털: 원두 주문, 음료 커스텀 옵션, 적립금 혜택 및 사전 포장 주문 사이트.",
    "showcase.desc_tn16": "피트니스 & 퍼스널 코칭 허브: 운동 루틴, 전담 트레이너 예약, 신체 변화 기록 및 영양 가이드를 제공하는 웰니스 플랫폼.",
    "showcase.type_tn01": "온라인 학습",
