    "showcase.desc_tn19": "가구 및 홈 인테리어 쇼핑몰 포털: 가상 쇼룸, 제품 카탈로그, 인테리어 스타일링 제안 및 간편 결제 기능을 갖춘 통합 가구 주문 시스템.",
