    "site2026.about_desc": "La Agencia Nacional de Innovación (Organización Pública) o NIA reconoce la importancia de desarrollar continuamente el sistema nacional de innovación y el ecosistema de startups. Este año, Startup x Innovation Tailandia Expo 2026 o SITE 2026 se organiza bajo el concepto 'Impacto de la innovación global: el año de la inversión' para reunir redes globales de innovación, elevar la cooperación y promover el intercambio de conocimientos para fortalecer el ecosistema.",
    "site2026.objective_title": "Objetivos",
