    "home.badge": "Zona de pruebas WebAvatar",
    "home.hero_title": "Conozca a su representante digital",
    "home.hero_subtitle": "Botnoi Group presenta el escaparate definitivo para agentes de WebAvatar. Esta zona de pruebas unificada presenta tres aplicaciones empresariales localizadas configuradas para voz automatizada, llenado de formularios y enrutamiento de páginas.",
    "home.btn_explore": "Explore los casos de uso de demostración",
    "home.btn_tech": "Cómo funciona la navegación",
    "home.mockup_title": "Representante Digital WebAvatar",
    "home.mockup_desc": "Nuestro avatar visual lee las estructuras de las páginas web, completa entradas complejas, selecciona elementos desplegables y maneja la navegación internamente. Intente pronunciar comandos como \"ir a la reserva de vuelo\" o \"muéstrame la opción de comida con curry verde\".",
    "home.btn_request_live": "Solicitar demostración en vivo",
    "home.btn_launch_usecases": "Lanzar casos de uso",
    "home.mockup_avatar_title": "Botnoi - Avatar digital",
    "home.mockup_awaiting": "ESPERANDO COMANDO...",
    "home.stats_clients": "Clientes activos",
    "home.stats_voices": "Voces Realistas",
    "home.stats_languages": "Idiomas admitidos",
    "home.select_usecase": "Seleccione un caso de uso de demostración",
    "home.usecase_subtitle": "Elija una aplicación empresarial interactiva a continuación. Todas las rutas son detectables por el escáner WebAvatar.",
    "home.card_flight_title": "Reserva de vuelos de BotnoiAir",
    "home.card_flight_desc": "Un sistema localizado de reservas de aerolíneas nacionales. Incluye filtros de búsqueda de ida y vuelta, selectores de recuento de pasajeros, opciones de códigos de promoción, un modal de tarjeta de embarque generado y una lista completa de reservas de administrador.",
    "home.card_flight_cta": "Iniciar la demostración de reserva de vuelos",
    "home.card_food_title": "TN01-TN20 Portal de espacio de trabajo adaptable",
    "home.card_food_desc": "Un portal de espacio de trabajo adaptable para 20 casas (TN01-TN20) que admite tipos de proyectos dinámicos (alojamiento, reserva de vuelos, restaurante, comercio electrónico). Seleccione House 7 (TN07) para probar la demostración de comedor orgánico con servicio de habitaciones.",
    "home.card_food_cta": "Lanzamiento del Portal de la Casa TN",
    "home.card_alldemo_title": "Todas las demostraciones (TN01-TN20)",
    "home.card_alldemo_desc": "Explore todas las aplicaciones sandbox interactivas y proyectos web estudiantiles (TN01–TN20), incluyendo reserva de vuelos, comercio electrónico de IT Store y presentaciones estudiantiles.",
    "home.card_alldemo_cta": "Iniciar portal de todas las demostraciones",
    "home.card_itstore_title": "Tienda de TI de Botnoi: comercio electrónico",
    "home.card_itstore_desc": "Una tienda minorista de tecnología con todas las funciones. Explore computadoras portátiles, monitores, audio y accesorios. Muestra filtrado de categorías, gestión de carritos, pago de facturas y un panel de administración de pedidos con navegación completa por comandos de voz de WebAvatar.",
    "home.card_itstore_cta": "Inicie la demostración de la tienda de TI",
    "home.card_hotel_title": "Botnoi Grand Hotel & Resort — Reserva de Hotel",
    "home.card_hotel_desc": "Sandbox interactivo de reserva de habitaciones de hotel y resort. Incluye selección de habitaciones, filtro de fechas, gestión de huéspedes y navegación por voz WebAvatar.",
    "home.card_hotel_cta": "Iniciar Demo de Hotel",
    "home.card_contact_title": "Formulario de consulta de ventas B2B",
    "home.card_contact_desc": "Un formulario de captura de generación de leads de nivel de producción. Incluye estados de validación, selección desplegable dinámica de tipos de consultas, acordeones interactivos de preguntas frecuentes y una lista de envío de consultas en la zona de pruebas.",
    "home.card_contact_cta": "Lanzar la demostración de consultas B2B",
    "home.tech_title": "Motor WebAvatar",
    "home.tech_subtitle": "Ejecución unificada del agente e interoperabilidad del sitio",
    "home.tech_desc": "A diferencia de los bots estándar basados ​​en texto, WebAvatar escanea el DOM e interactúa directamente con los elementos. Logra una navegación fluida y una baja sobrecarga de tokens al cumplir con las siguientes reglas:",
    "home.rule1_title": "01 / Enrutamiento basado en eventos",
    "home.rule1_desc": "Cuando el agente decide realizar la transición a una nueva página, envía un CustomEvent cancelable 'webavatar-navigate'. Nuestro enrutamiento de página única intercepta este evento y actualiza React Router, evitando recargas duras de páginas y manteniendo intacta la sesión de voz.",
    "home.rule2_title": "02 / Ganchos de enfoque declarativo",
    "home.rule2_desc": "Anclamos elementos utilizando ID únicos (por ejemplo, #nav-flight, #nav-contact). El motor WebAvatar lee estos anclajes y activa dinámicamente un desplazamiento suave, animaciones visuales de anillos focales y resaltados asociados al habla.",
    "home.rule3_title": "03 / Validación de entrada redundante",
    "home.rule3_desc": "Todos los formularios del lado del cliente están conectados a validaciones de entrada HTML5 estándar y activan indicadores de éxito reactivos. Cuando el agente WebAvatar completa un campo, envía eventos de entrada nativos para actualizar correctamente los estados de los componentes de React.",
    "home.tech_cta": "Implemente WebAvatar en su sitio",
    "home.features_heading": "Características y limitaciones del motor",
    "home.feat1": "Admite el análisis continuo de escritura tailandesa",
    "home.feat2": "Proyección de coordenadas de ventana gráfica dinámica",
    "home.feat3": "Transiciones de modelos de habla bilingüe",
    "home.feat4": "Cero cookies o scripts de terceros de seguimiento",
