    "about.badge": "Nuestra Identidad",
    "about.title": "Inteligencia conversacional pionera",
    "about.subtitle": "Botnoi Group se fundó con una misión singular: hacer que la inteligencia artificial avanzada sea accesible, hiperlocalizada y altamente transaccional para las empresas del sudeste asiático.",
    "about.purpose_title": "Nuestro propósito",
    "about.purpose_desc1": "Creemos que la interacción hombre-máquina debe ser fluida, natural y altamente intuitiva. Al unir la PNL conversacional, la acústica humana sintética y los avatares digitales 3D interactivos, creamos las fuerzas laborales digitales del mañana.",
    "about.purpose_desc2": "Ya sea automatizando la atención al cliente de alta frecuencia o guiando a los pacientes a través de complejos portales de atención médica, las soluciones de Botnoi Group están diseñadas para escalar con una confiabilidad sin concesiones.",
    "about.vision_title": "Nuestra Visión",
    "about.vision_desc": "Convertirse en el estándar absoluto para la tecnología humana digital y de voz del sudeste asiático. Capacitamos a las pequeñas y medianas empresas y empresas regionales para que implementen agentes virtuales de última generación que brinden una satisfacción excepcional al cliente.",
    "about.vision_cta": "Conéctese con nuestros ingenieros",
    "about.journey_title": "El viaje de Botnoi",
    "about.journey_subtitle": "Recorriendo nuestra historia desde una startup especializada en IA en Bangkok hasta un líder humano digital regional.",
    "about.timeline_2018_title": "Fundación de la empresa",
    "about.timeline_2018_desc": "Botnoi Group fue establecido en Bangkok, Tailandia, por un grupo dedicado de lingüistas computacionales e ingenieros de redes neuronales centrados en la construcción de modelos de análisis tailandés especializados.",
    "about.timeline_2020_title": "Lanzamiento de la IA de Botnoi",
    "about.timeline_2020_desc": "Lanzamos nuestra plataforma insignia AI Chatbot de código bajo (Botnoi.ai). La plataforma creció rápidamente, impulsando los flujos de chat de atención al cliente para más de 5000 clientes corporativos en LINE OA y Facebook Messenger.",
    "about.timeline_2022_title": "Lanzamiento de voz de Botnoi",
    "about.timeline_2022_desc": "Presentamos nuestro motor de texto a voz (TTS) de última generación, que presenta más de 100 voces sintéticas casi humanas en 10 idiomas del sudeste asiático. Adoptado por los principales canales hospitalarios y sectores públicos.",
    "about.timeline_2026_title": "WebAvatar y humanos virtuales",
    "about.timeline_2026_desc": "Pionero en la integración de agentes virtuales 3D directamente integrados en las capas del sitio web. Se lanzó WebAvatar, que permite a los agentes virtuales hablar verbalmente, responder preguntas complejas de los usuarios y realizar desplazamientos y enrutamientos autónomos por sitios web.",
    "about.competency_title": "Nuestras competencias principales",
    "about.competency_subtitle": "Sistemas patentados diseñados y mantenidos internamente por la división de investigación de Botnoi.",
    "about.comp1_title": "01 / Tokenizadores personalizados del sudeste asiático",
    "about.comp1_desc": "A diferencia de los marcos de PNL occidentales que luchan con lenguajes de escritura continua (como el tailandés, el laosiano y el birmano) que carecen de límites claros para las palabras, los modelos de tokenización patentados de Botnoi analizan oraciones continuas con hasta un 98% de precisión.",
    "about.comp2_title": "02 / Voces sintéticas clonadas acústicas",
    "about.comp2_desc": "Nuestros laboratorios del habla clonan voces humanas a partir de menos de 30 minutos de audio de muestra de alta calidad. Generamos acústica natural con estados emocionales personalizables, variaciones de ritmo y acentos localizados adecuados para audiencias regionales.",
    "about.comp3_title": "03 / Colaboración multiagente",
    "about.comp3_desc": "Construimos canales de agentes colaborativos especializados. Bajo una única interfaz de avatar, diferentes subagentes se coordinan entre sí para resolver transacciones complejas, pasar datos de la memoria contextual y ejecutar acciones de la base de datos administrativa.",
    "about.comp4_title": "04 / Mapeo DOM interactivo",
    "about.comp4_desc": "Los agentes de WebAvatar utilizan la reflexión DOM del navegador en tiempo real. Cuando un cliente pregunta \"¿Dónde están sus precios?\", el humano virtual lee la solicitud, activa el desplazamiento de la página, resalta la fila de precios solicitada y revisa verbalmente las características del nivel.",
    "about.team_title": "Nuestro equipo de liderazgo",
    "about.team_subtitle": "Conozca a los visionarios que dirigen nuestra cartera de productos, la investigación lingüística y la estrategia comercial regional.",
    "about.team1_role": "Fundador y director ejecutivo",
    "about.team1_desc": "Se especializa en redes neuronales computacionales y estrategia de negocios regionales.",
    "about.team2_role": "Director de Tecnologías del Habla",
    "about.team2_desc": "Supervisa el modelado de texto a voz y los sistemas de clonación de voz emocional.",
    "about.team3_role": "Jefe de Procesamiento del Lenguaje Natural",
    "about.team3_desc": "Dirige la investigación y el desarrollo centrales para la tokenización del sudeste asiático y el desarrollo de procesos de PNL.",
    "about.team4_role": "Ingeniero líder de producto, WebAvatar",
    "about.team4_desc": "Gestiona los SDK de integración del navegador, las capas de representación y los complementos de enrutamiento SPA.",
