    "showcase.desc_accommodation": "Reserva de hoteles y complejos: Sistema de reservas completo con catálogos de habitaciones, selectores de fechas, cálculos de tarifas y pantallas de confirmación.",
    "showcase.desc_flight": "Motor de reservas de vuelos: Portal de reservas de aerolíneas nacionales con datos interactivos de pasajeros, mapas de asientos y generación de tarjetas de embarque simuladas.",
    "showcase.desc_restaurant": "Aplicación de pedidos de restaurante: Aplicación de pedidos de menú digital con categorización de artículos, carrito de compras, facturación y recibos en tiempo real.",
    "showcase.desc_ecommerce": "Tienda de tecnología en línea: Sitio completo de venta al por menor con filtros de categorías, actualizaciones de carrito de compras y facturación.",
    "showcase.desc_tn01": "Centro de aprendizaje en línea: Plataforma educativa integral con catálogo de cursos, lecciones en video, seguimiento de progreso y certificados.",
    "showcase.desc_tn03": "Tienda de cuidado de la piel y belleza: Tienda dermatológica premium con análisis de piel, rutinas de cuidado, carrito y pago en línea.",
    "showcase.desc_tn04": "Portal de mapas e itinerarios: Plataforma de exploración geográfica con mapas de rutas interactivos, búsqueda de lugares y guía turística.",
    "showcase.desc_tn05": "Portal de hospital y servicios médicos: Plataforma de salud moderna con reserva de citas médicas, directorio de especialidades y paquetes de salud.",
    "showcase.desc_tn06": "Plataforma API Botnoi AI para desarrolladores: Portal integral de servicios de IA en tailandés con voz a texto, texto a voz, clonación de voz, SDK y planes de suscripción.",
    "showcase.desc_tn07": "Aplicación de restaurante y pedidos digitales: Menú digital interactivo, reserva de mesas en línea, pedidos personalizados y facturación al instante.",
    "showcase.desc_tn09": "Plataforma de traducción de voz e IA en tiempo real y TTS: Sistema avanzado de traducción de voz a voz con síntesis de texto a voz multilingüe instantánea y reproducción de audio.",
    "showcase.desc_tn10": "Reserva de servicio y reparación de aire acondicionado: Portal de mantenimiento profesional con agenda de técnicos, paquetes de limpieza y seguimiento.",
    "showcase.desc_tn11": "Portal de farmacia y consulta farmacéutica en línea: Plataforma de salud integral para consultar farmacéuticos colegiados, compra de medicamentos, orientación de síntomas y envío a domicilio.",
    "showcase.desc_tn14": "Portal de cafetería y café de especialidad: Tienda de café artesanal con venta de granos, personalización de bebidas y pedidos anticipados.",
    "showcase.desc_tn16": "Centro de fitness y entrenamiento personal: Plataforma de bienestar integral con planes de ejercicios, reserva de entrenadores y guía de nutrición.",
