    "home.badge": "Bac à sable WebAvatar",
    "home.hero_title": "Rencontrez votre représentant numérique",
    "home.hero_subtitle": "Botnoi Group présente la vitrine ultime pour les agents WebAvatar. Ce bac à sable unifié comprend trois applications métier localisées configurées pour l'automatisation de la parole, du remplissage de formulaires et du routage des pages.",
    "home.btn_explore": "Explorez les cas d'utilisation de démonstration",
    "home.btn_tech": "Comment fonctionne la navigation",
    "home.mockup_title": "Représentant numérique WebAvatar",
    "home.mockup_desc": "Notre avatar visuel lit les structures des pages Web, remplit des entrées complexes, sélectionne les éléments des listes déroulantes et gère la navigation en interne. Essayez de prononcer des commandes telles que « aller à la réservation de vol » ou « montrez-moi l'option de nourriture au curry vert ».",
    "home.btn_request_live": "Demander une démo en direct",
    "home.btn_launch_usecases": "Cas d'utilisation de lancement",
    "home.mockup_avatar_title": "Botnoi - Avatar numérique",
    "home.mockup_awaiting": "EN ATTENTE DE COMMANDE...",
    "home.stats_clients": "Clients actifs",
    "home.stats_voices": "Voix réalistes",
    "home.stats_languages": "Langues prises en charge",
    "home.select_usecase": "Sélectionnez un cas d'utilisation de démonstration",
    "home.usecase_subtitle": "Choisissez une application métier interactive ci-dessous. Tous les itinéraires sont détectables par le scanner WebAvatar.",
    "home.card_flight_title": "Réservation de vol BotnoiAir",
    "home.card_flight_desc": "Un système de réservation de compagnies aériennes nationales localisé. Comprend des filtres de recherche aller-retour, des sélecteurs de nombre de passagers, des options de code promotionnel, un modal de carte d'embarquement généré et une liste complète de réservation d'administrateur.",
    "home.card_flight_cta": "Lancer la démo de réservation de vols",
    "home.card_food_title": "Portail d'espace de travail adaptatif TN01-TN20",
    "home.card_food_desc": "Un portail d'espace de travail adaptatif pour 20 maisons (TN01-TN20) prenant en charge des types de projets dynamiques (hébergement, réservation de vols, restaurant, commerce électronique). Sélectionnez House 7 (TN07) pour tester la démo de restauration bio avec service en chambre.",
    "home.card_food_cta": "Lancer le portail TN House",
    "home.card_alldemo_title": "Toutes les démos (TN01-TN20)",
    "home.card_alldemo_desc": "Explorez toutes les applications bac à sable interactives et projets web étudiants (TN01–TN20), y compris la réservation de vols, l'IT Store e-commerce et les vitrines étudiantes.",
    "home.card_alldemo_cta": "Lancer le portail de toutes les démos",
    "home.card_itstore_title": "Botnoi IT Shop — Commerce électronique",
    "home.card_itstore_desc": "Une vitrine de vente au détail technologique complète. Parcourez les ordinateurs portables, les moniteurs, l’audio et les accessoires. Démontre le filtrage des catégories, la gestion des paniers, le paiement des factures et un tableau de bord de commande d'administration avec navigation complète par commande vocale WebAvatar.",
    "home.card_itstore_cta": "Lancer la démo de l'IT Store",
    "home.card_hotel_title": "Botnoi Grand Hotel & Resort — Réservation d'Hôtel",
    "home.card_hotel_desc": "Bac à sable interactif de réservation de chambres d'hôtel et resort. Offre la sélection de chambres, filtres de dates, gestion des clients et navigation vocale WebAvatar.",
    "home.card_hotel_cta": "Lancer la Démo Hôtel",
    "home.card_contact_title": "Formulaire de demande de vente B2B",
    "home.card_contact_desc": "Un formulaire de capture de génération de leads de qualité production. Comprend les états de validation, une sélection déroulante dynamique des types de requêtes, des accordéons FAQ interactifs et une liste de soumissions de requêtes sandbox.",
    "home.card_contact_cta": "Lancer la démo d'enquête B2B",
    "home.tech_title": "Moteur WebAvatar",
    "home.tech_subtitle": "Exécution unifiée des agents et interopérabilité des sites",
    "home.tech_desc": "Contrairement aux robots textuels standard, WebAvatar analyse le DOM et interagit directement avec les éléments. Il permet une navigation fluide et une faible surcharge de jetons en adhérant aux règles suivantes :",
    "home.rule1_title": "01 / Routage piloté par les événements",
    "home.rule1_desc": "Lorsque l'agent décide de passer à une nouvelle page, il envoie un CustomEvent annulable « webavatar-navigate ». Notre routage sur une seule page intercepte cet événement et met à jour React Router, empêchant ainsi les rechargements de pages matérielles et préservant la session vocale intacte.",
    "home.rule2_title": "02 / Crochets de focus déclaratifs",
    "home.rule2_desc": "Nous ancrons les éléments à l'aide d'identifiants uniques (par exemple #nav-flight, #nav-contact). Le moteur WebAvatar lit ces ancres et déclenche dynamiquement un défilement fluide, des animations visuelles en anneau focal et des surbrillance associées à la parole.",
    "home.rule3_title": "03 / Validation des entrées redondantes",
    "home.rule3_desc": "Tous les formulaires côté client sont connectés aux validations d'entrée HTML5 standard et déclenchent des indicateurs de réussite réactifs. Lorsque l'agent WebAvatar remplit un champ, il distribue des événements d'entrée natifs pour mettre à jour correctement les états des composants React.",
    "home.tech_cta": "Déployez WebAvatar sur votre site",
    "home.features_heading": "Caractéristiques et contraintes du moteur",
    "home.feat1": "Prend en charge l'analyse continue des scripts thaïlandais",
    "home.feat2": "Projection de coordonnées de fenêtre dynamique",
    "home.feat3": "Transitions du modèle de parole bilingue",
    "home.feat4": "Zéro suivi de cookies ou de scripts tiers",
