    "itstore_item.curve32.desc": "Superbe écran 4K incurvé avec un taux de rafraîchissement ultra-fluide. Parfait pour les jeux et la productivité côte à côte.",
    "itstore_item.mechkey.name": "BotnKey Mécanicien Pro",
