    "about.badge": "Notre identité",
    "about.title": "Intelligence conversationnelle pionnière",
    "about.subtitle": "Botnoi Group a été fondé avec une mission unique : rendre l'intelligence artificielle avancée accessible, hyper-localisée et hautement transactionnelle pour les entreprises d'Asie du Sud-Est.",
    "about.purpose_title": "Notre objectif",
    "about.purpose_desc1": "Nous pensons que l’interaction homme-machine doit être fluide, naturelle et hautement intuitive. En reliant la PNL conversationnelle, l’acoustique humaine synthétique et les avatars numériques 3D interactifs, nous créons la main-d’œuvre numérique de demain.",
    "about.purpose_desc2": "Qu'il s'agisse d'automatiser le service client à haute fréquence ou de guider les patients à travers des portails de soins de santé complexes, les solutions du groupe Botnoi sont conçues pour évoluer avec une fiabilité sans compromis.",
    "about.vision_title": "Notre Vision",
    "about.vision_desc": "Devenir la norme absolue en matière de technologie vocale et humaine numérique en Asie du Sud-Est. Nous permettons aux petites et moyennes entreprises régionales de déployer des agents virtuels de pointe qui offrent une satisfaction client exceptionnelle.",
    "about.vision_cta": "Connectez-vous avec nos ingénieurs",
    "about.journey_title": "Le voyage de Botnoï",
    "about.journey_subtitle": "Retraçant notre histoire depuis une startup spécialisée en IA à Bangkok jusqu'à un leader humain numérique régional.",
    "about.timeline_2018_title": "Fondation d'entreprise",
    "about.timeline_2018_desc": "Le groupe Botnoi a été créé à Bangkok, en Thaïlande, par une cohorte dédiée de linguistes informatiques et d'ingénieurs en réseaux neuronaux axés sur la création de modèles d'analyse thaïlandais spécialisés.",
    "about.timeline_2020_title": "Lancement de l'IA Botnoi",
    "about.timeline_2020_desc": "Lancement de notre plateforme phare de chatbot IA low-code (Botnoi.ai). La plateforme a rapidement évolué, alimentant les flux de discussion du support client pour plus de 5 000 entreprises clientes sur LINE OA et Facebook Messenger.",
    "about.timeline_2022_title": "Déploiement de la voix Botnoi",
    "about.timeline_2022_desc": "Dévoilement de notre moteur de synthèse vocale (TTS) de pointe, introduisant plus de 100 voix synthétiques quasi humaines dans 10 langues d'Asie du Sud-Est. Adopté par les principales filières hospitalières et les secteurs publics.",
    "about.timeline_2026_title": "WebAvatar et humains virtuels",
    "about.timeline_2026_desc": "Pionnier dans l'intégration d'agents virtuels 3D directement intégrés dans les couches de sites Web. Lancement de WebAvatar, permettant aux agents virtuels de parler verbalement, de répondre aux questions complexes des utilisateurs et d'effectuer un défilement et un routage autonomes du site Web.",
    "about.competency_title": "Nos compétences clés",
    "about.competency_subtitle": "Systèmes exclusifs conçus et entretenus en interne par la division de recherche de Botnoi.",
    "about.comp1_title": "01 / Tokenizers personnalisés d'Asie du Sud-Est",
    "about.comp1_desc": "Contrairement aux cadres PNL occidentaux qui ont du mal avec les langages à script continu (tels que le thaï, le laotien et le birman) qui manquent de limites claires entre les mots, les modèles de tokenisation propriétaires de Botnoi analysent les phrases continues avec une précision allant jusqu'à 98 %.",
    "about.comp2_title": "02 / Voix synthétiques clonées acoustiques",
    "about.comp2_desc": "Nos laboratoires vocaux clonent des voix humaines à partir de moins de 30 minutes d’échantillons audio de haute qualité. Nous générons une acoustique naturelle avec des états émotionnels personnalisables, des variations de rythme et des accents localisés adaptés aux publics régionaux.",
    "about.comp3_title": "03 / Collaboration Multi-Agents",
    "about.comp3_desc": "Nous construisons des pipelines d’agents collaboratifs spécialisés. Sous une interface avatar unique, différents sous-agents se coordonnent pour résoudre des transactions complexes, transmettre des données de mémoire contextuelles et exécuter des actions de base de données de back-office.",
    "about.comp4_title": "04 / Cartographie DOM interactive",
    "about.comp4_desc": "Les agents WebAvatar utilisent la réflexion DOM du navigateur en temps réel. Lorsqu'un client demande « Où sont vos prix ? », l'humain virtuel lit la demande, déclenche le défilement de la page, met en surbrillance la ligne de tarification demandée et examine verbalement les fonctionnalités du niveau.",
    "about.team_title": "Notre équipe de direction",
    "about.team_subtitle": "Rencontrez les visionnaires qui dirigent nos pipelines de produits, nos recherches linguistiques et notre stratégie commerciale régionale.",
    "about.team1_role": "Fondateur et PDG",
    "about.team1_desc": "Spécialisé dans les réseaux de neurones informatiques et la stratégie commerciale régionale.",
    "about.team2_role": "Directeur des technologies vocales",
    "about.team2_desc": "Supervise la modélisation de la synthèse vocale et les systèmes de clonage de la parole émotionnelle.",
    "about.team3_role": "Responsable du traitement du langage naturel",
    "about.team3_desc": "Dirige la R&D de base pour la tokenisation en Asie du Sud-Est et le développement du pipeline NLP.",
    "about.team4_role": "Ingénieur produit principal, WebAvatar",
    "about.team4_desc": "Gère les SDK d'intégration du navigateur, les couches de rendu et les plugins de routage SPA.",
