    "contact.title": "Améliorons votre expérience numérique",
    "contact.subtitle": "Vous avez des questions sur le déploiement de WebAvatar sur votre site ou sur l'intégration de modèles conversationnels personnalisés ? Envoyez-nous un message et notre équipe vous répondra sous peu.",
